actions.script:
import groovy.json.JsonSlurper
import groovy.json.JsonOutput
import java.security.MessageDigest

ec.logger.info("[PROCESS#PAYLOAD] context: ${context}")
// 1. Map mode string to enumId
Map modeMap = [
    'plan': 'AamPlan', 'build': 'AamBuild', 'orchestrate': 'AamOrchestrate',
    'test': 'AamTest', 'query': 'AamQuery', 'history': 'AamHistory', 'discuss': 'AamDiscuss'
]
String modeEnumId = modeMap.get(mode.toLowerCase()) ?: 'AamPlan'

// 2. Normalize and compute content hash
Map rawPayloadMap = payload ?: [:]
if (userPromptText) rawPayloadMap.userPromptText = userPromptText
String payloadJsonStr = JsonOutput.toJson(rawPayloadMap)

MessageDigest md = MessageDigest.getInstance("SHA-256")
String sha256Hex = md.digest(payloadJsonStr.getBytes("UTF-8")).encodeHex().toString()

// 3. Resolve or create AgiArtifact
String artId = null
if (artifactUri) {
    def artVal = ec.entity.find("org.moqui.ai.AgiArtifact").condition("artifactPath", artifactUri).one()
    if (!artVal) {
        artVal = ec.entity.makeValue("org.moqui.ai.AgiArtifact")
        artVal.artifactPath = artifactUri
        artVal.artifactStatusEnumId = "AasDraft"
        artVal.setSequencedIdPrimary()
        artVal.create()
    }
    artId = artVal.agiArtifactId
}

// 4. Create or Update AgiPayload entity
def payloadVal = agiPayloadId ? ec.entity.find("org.moqui.ai.payload.AgiPayload").condition("agiPayloadId", agiPayloadId).one() : null
if (!payloadVal) {
    payloadVal = ec.entity.makeValue("org.moqui.ai.payload.AgiPayload")
    payloadVal.setSequencedIdPrimary()
    payloadVal.createdDate = ec.user.nowTimestamp
    payloadVal.statusId = "PlsDraft"
} else {
    payloadVal.revisionNumber = (payloadVal.revisionNumber ?: 1) + 1
}

payloadVal.modeEnumId = modeEnumId
payloadVal.targetComponent = targetComponent
payloadVal.artifactUri = artifactUri
payloadVal.targetMariaId = targetMariaId
payloadVal.agiArtifactId = artId
payloadVal.title = title ?: (userPromptText ? (userPromptText.length() > 50 ? userPromptText.substring(0, 47) + "..." : userPromptText) : "Untitled Payload")
payloadVal.userPromptText = userPromptText
payloadVal.payloadJsonData = payloadJsonStr
payloadVal.contentSha256 = sha256Hex
payloadVal.lastUpdatedStamp = ec.user.nowTimestamp

// 5. Contextual Intent Promotion: Map Prompt -> WorkEffort Intent Node
if (["AamBuild", "AamTest", "AamDiscuss"].contains(modeEnumId) && artId) {
    String weType = modeEnumId == "AamDiscuss" ? "WetDiscussion" : "WetIntent"
    String safeMariaId = targetMariaId ?: (artifactUri ? org.moqui.ide.ScreenEditorServices.generateMariaId(artifactUri, "root") : null)

    Map weResult = ec.service.sync().name("org.moqui.ide.BlueprintServices.create#WorkEffortNode").parameters([
        workEffortName: payloadVal.title,
        agiArtifactId: artId,
        sourceReferenceId: artifactUri,
        workEffortTypeEnumId: weType,
        targetMariaId: safeMariaId
    ]).call()

    payloadVal.workEffortId = weResult.workEffortId
}

payloadVal.createOrUpdate()
context.agiPayloadId = payloadVal.agiPayloadId
context.workEffortId = payloadVal.workEffortId

// 6. Persist key-value Facets
if (facets instanceof Map) {
    facets.each { k, v ->
        if (k && v != null) {
            def facetVal = ec.entity.makeValue("org.moqui.ai.payload.AgiPayloadFacet")
            facetVal.setSequencedIdPrimary()
            facetVal.agiPayloadId = payloadVal.agiPayloadId
            facetVal.facetKey = k.toString()
            facetVal.facetValue = v.toString()
            facetVal.create()
        }
    }
}

// 7. Mode-Specific Pipeline Execution
Map execResult = [:]
if (modeEnumId == "AamBuild") {
    if (rawPayloadMap.stagedAstMutation && artifactUri) {
        payloadVal.statusId = "PlsExecuting"
        payloadVal.update()

        String astJson = JsonOutput.toJson(rawPayloadMap.stagedAstMutation)
        ec.service.sync().name("org.moqui.ide.AgiIdeServices.store#WorkspaceBuffer")
            .parameters([artifactUri: artifactUri, metaJsonBuffer: astJson])
            .call()
        ec.service.sync().name("org.moqui.ide.AgiIdeServices.save#ScreenXml")
            .parameters([artifactUri: artifactUri, metaJsonBuffer: astJson])
            .call()

        payloadVal.statusId = "PlsCommitted"
        execResult.status = "SUCCESS"
        execResult.message = "Successfully applied AST mutation to ${artifactUri}"
    } else {
        payloadVal.statusId = "PlsStaged"
        execResult.status = "STAGED"
        execResult.message = "Build payload staged for AI assistant code generation."
    }
} else if (modeEnumId == "AamTest") {
    payloadVal.statusId = "PlsStaged"
    execResult.status = "READY"
    execResult.message = "Test payload ready for execution in test harness."
} else {
    payloadVal.statusId = "PlsDraft"
    execResult.status = "RECORDED"
    execResult.message = "Payload context and intent saved."
}

payloadVal.executionResultJson = JsonOutput.toJson(execResult)
payloadVal.update()

context.statusId = payloadVal.statusId
context.executionResult = execResult

import groovy.json.JsonSlurper

def pld = ec.entity.find("org.moqui.ai.payload.AgiPayload").condition("agiPayloadId", agiPayloadId).one()
if (!pld) {
    ec.message.addError("AgiPayload not found for ID: ${agiPayloadId}")
    return
}

Map outMap = pld.getMap()
if (pld.payloadJsonData) {
    try {
        outMap.payload = new JsonSlurper().parseText(pld.payloadJsonData)
    } catch (Exception ignore) {}
}
if (pld.executionResultJson) {
    try {
        outMap.executionResult = new JsonSlurper().parseText(pld.executionResultJson)
    } catch (Exception ignore) {}
}

def facets = ec.entity.find("org.moqui.ai.payload.AgiPayloadFacet").condition("agiPayloadId", agiPayloadId).list()
outMap.facets = facets.collectEntries { [(it.facetKey): it.facetValue] }

context.payloadDetails = outMap

import groovy.json.JsonSlurper
import groovy.json.JsonOutput
import org.moqui.resource.ResourceReference

String activeUserId = userId ?: ec.user.getUserId() ?: "system_ide_user"

// Canonical URI Normalization
String rawUri = artifactUri ? artifactUri.trim().replace('\\', '/') : ""
String effectiveUri = rawUri
if (effectiveUri.contains("runtime/component/")) {
    effectiveUri = "component://" + effectiveUri.substring(effectiveUri.indexOf("runtime/component/") + "runtime/component/".length())
}

boolean isNonXml = effectiveUri.endsWith('.md') || effectiveUri.endsWith('.json') || 
                   effectiveUri.endsWith('.txt') || effectiveUri.endsWith('.csv') ||
                   effectiveUri.endsWith('.groovy')

ec.logger.warn("🔍 [get#WorkspaceBuffer] REQUEST: rawUri=[${rawUri}], effectiveUri=[${effectiveUri}], isNonXml=[${isNonXml}], user=[${activeUserId}], forceReload=[${forceReloadFromDisk}]")

long diskLastModified = 0
ResourceReference rr = ec.resource.getLocationReference(effectiveUri)
if (rr != null && rr.exists) {
    diskLastModified = rr.getLastModified()
}

def bufferList = ec.entity.find("org.moqui.ai.WorkspaceBuffer")
    .condition("artifactUri", effectiveUri)
    .condition("userId", activeUserId)
    .orderBy("-lastUpdatedStamp")
    .useCache(false)
    .list()

def bufferRow = bufferList ? bufferList[0] : null
ec.logger.warn("🔍 [get#WorkspaceBuffer] DB LOOKUP: matched=${bufferList.size()} row(s), activeRowId=${bufferRow?.workspaceBufferId}, lastUpdated=${bufferRow?.lastUpdatedStamp}, diskMod=${diskLastModified}")

boolean forceReload = forceReloadFromDisk
if (bufferRow != null && diskLastModified > 0) {
    long bufferTime = bufferRow.lastUpdatedStamp ? bufferRow.lastUpdatedStamp.time : 0
    if (diskLastModified > bufferTime) {
        ec.logger.warn("🔄 [get#WorkspaceBuffer] Disk is newer than DB (${diskLastModified} > ${bufferTime}). Invalidation triggered for: ${effectiveUri}")
        forceReload = true
    }
}

// Self-healing detection: Only check AST tokens if this is an XML file
if (bufferRow?.metaJsonBuffer && !forceReload) {
    if (!isNonXml) {
        String rawJson = bufferRow.metaJsonBuffer
        if (rawJson.contains('"name":"subscreens-item"') || (rawJson.contains('"children":[]') && !rawJson.contains('form-single') && !rawJson.contains('field') && !rawJson.contains('subscreens'))) {
            ec.logger.warn("🩹 [get#WorkspaceBuffer] Corrupted AST detected in DB row [${bufferRow.workspaceBufferId}]. Healing from disk.")
            forceReload = true
        }
    }
} else {
    forceReload = true
}

if (bufferRow?.metaJsonBuffer && !forceReload) {
    context.workspaceBufferId = bufferRow.workspaceBufferId
    context.metaJsonBuffer = bufferRow.metaJsonBuffer
    context.isDiskNewer = false
    ec.logger.warn("✅ [get#WorkspaceBuffer] RETURNING CACHED ROW [${bufferRow.workspaceBufferId}]")
} else {
    // Check if non-XML file (e.g. component.md)
    if (isNonXml) {
        ec.logger.info("📄 [get#WorkspaceBuffer] Loading raw text for non-XML artifact: ${effectiveUri}")
        String fileText = ""
        if (rr != null && rr.exists) {
            fileText = rr.getText() ?: ""
        }
        Map storeResult = ec.service.sync().name("org.moqui.ide.AgiIdeServices.store#WorkspaceBuffer")
            .parameters([
                workspaceBufferId: bufferRow?.workspaceBufferId,
                artifactUri: effectiveUri, 
                userId: activeUserId, 
                metaJsonBuffer: fileText
            ])
            .call()

        context.workspaceBufferId = storeResult?.workspaceBufferId ?: bufferRow?.workspaceBufferId ?: ""
        context.metaJsonBuffer = fileText
        context.isDiskNewer = true
        ec.logger.info("💾 [get#WorkspaceBuffer] STORED RAW TEXT BUFFER into row [${context.workspaceBufferId}] for ${effectiveUri}")
    } else {
        ec.logger.warn("📄 [get#WorkspaceBuffer] PARSING FRESH XML FROM DISK for: ${effectiveUri}")
        Map parseResult = ec.service.sync().name("org.moqui.ide.AgiIdeServices.parse#XmlToTree")
            .parameter("artifactUri", effectiveUri)
            .call()

        if (parseResult?.layoutTree) {
            String jsonFromDisk = JsonOutput.toJson(parseResult.layoutTree)
            Map storeResult = ec.service.sync().name("org.moqui.ide.AgiIdeServices.store#WorkspaceBuffer")
                .parameters([
                    workspaceBufferId: bufferRow?.workspaceBufferId,
                    artifactUri: effectiveUri, 
                    userId: activeUserId, 
                    metaJsonBuffer: jsonFromDisk
                ])
                .call()

            context.workspaceBufferId = storeResult?.workspaceBufferId ?: bufferRow?.workspaceBufferId ?: ""
            context.metaJsonBuffer = jsonFromDisk
            context.isDiskNewer = true
            ec.logger.warn("💾 [get#WorkspaceBuffer] STORED FRESH DISK AST into row [${context.workspaceBufferId}]")
        } else {
            ec.logger.error("❌ [get#WorkspaceBuffer] Failed to parse layoutTree for: ${effectiveUri}")
        }
    }
}

                String activeUserId = userId ?: ec.user.getUserId() ?: "system_ide_user"
                String targetBufferId = workspaceBufferId

                // Canonical URI Normalization
                String rawUri = artifactUri ? artifactUri.trim().replace('\\', '/') : ""
                String effectiveUri = rawUri
                if (effectiveUri.contains("runtime/component/")) {
                    effectiveUri = "component://" + effectiveUri.substring(effectiveUri.indexOf("runtime/component/") + "runtime/component/".length())
                }

                // 🔍 TRACE CALLER STACK: Identify if this was called via REST or internal service
                List<String> callStack = []
                StackTraceElement[] stElements = Thread.currentThread().getStackTrace()
                for (int i = 0; i < Math.min(stElements.length, 18); i++) {
                    String line = stElements[i].toString()
                    if (line.contains("org.moqui") && !line.contains("getStackTrace")) {
                        callStack.add(line.replaceAll("org.moqui.", ""))
                    }
                }
                String callerTrace = callStack.take(5).join(" -> ")

                // 🔍 INSPECT AST CONTENTS FOR ENTITIES
                String bufStr = metaJsonBuffer ?: ""
                if (bufStr.contains("WorkEffortPartyPrp")) {
                    ec.logger.warn("🛑 [store#WorkspaceBuffer] Intercepted and blocked stale AST containing WorkEffortPartyPrp from client!")
                    return
                }
                boolean hasBadPrp = bufStr.contains("WorkEffortPartyPrp")
                boolean hasAssignment = bufStr.contains("WorkEffortPartyAssignment")
                boolean hasCanonical = bufStr.contains("mantle.work.effort.WorkEffortParty")

                ec.logger.warn("""
🚨 ====================================================================
🚨 [FORENSIC store#WorkspaceBuffer] INCOMING SAVE INVOCATION
🚨 Raw URI:         [${rawUri}]
🚨 Effective URI:   [${effectiveUri}]
🚨 Target BufferId: [${targetBufferId ?: 'NONE (Will query/insert)'}]
🚨 User:            [${activeUserId}]
🚨 Buffer Length:   ${bufStr.length()} chars
🚨 Entity Flags:    [WorkEffortPartyPrp=${hasBadPrp}] [WorkEffortPartyAssignment=${hasAssignment}] [WorkEffortParty=${hasCanonical}]
🚨 Call Origin:     ${callerTrace}
🚨 ====================================================================""")

                if (!targetBufferId) {
                    def existingList = ec.entity.find("org.moqui.ai.WorkspaceBuffer")
                        .condition("artifactUri", effectiveUri)
                        .condition("userId", activeUserId)
                        .orderBy("-lastUpdatedStamp")
                        .list()
                    if (existingList) {
                        targetBufferId = existingList[0].workspaceBufferId
                        ec.logger.warn("🔍 [FORENSIC store#WorkspaceBuffer] Resolved existing bufferId: [${targetBufferId}]")
                    }
                }

                def bufferValue = null
                if (targetBufferId) {
                    bufferValue = ec.entity.find("org.moqui.ai.WorkspaceBuffer")
                        .condition("workspaceBufferId", targetBufferId)
                        .one()
                }   
                if (bufferValue) {
                    bufferValue.artifactUri = effectiveUri
                    bufferValue.metaJsonBuffer = metaJsonBuffer
                    bufferValue.lastUpdatedStamp = ec.user.nowTimestamp
                    bufferValue.update()
                    ec.logger.warn("💾 [FORENSIC store#WorkspaceBuffer] UPDATED existing DB row [${targetBufferId}] for URI: ${effectiveUri}")
                } else {
                    bufferValue = ec.entity.makeValue("org.moqui.ai.WorkspaceBuffer")
                    bufferValue.artifactUri = effectiveUri
                    bufferValue.userId = activeUserId
                    bufferValue.metaJsonBuffer = metaJsonBuffer
                    bufferValue.setSequencedIdPrimary()
                    bufferValue.create()
                    targetBufferId = bufferValue.workspaceBufferId
                    ec.logger.warn("💾 [FORENSIC store#WorkspaceBuffer] CREATED new DB row [${targetBufferId}] for URI: ${effectiveUri}")
                }

                context.workspaceBufferId = targetBufferId

                import org.moqui.resource.ResourceReference
                import java.util.regex.Matcher
                import java.util.regex.Pattern

                def resolveFtlIncludes
                resolveFtlIncludes = { String loc, Set<String> visited ->
                    if (!loc) return ""

                    ResourceReference rr = ec.resource.getLocationReference(loc)
                    if (rr == null || !rr.exists) {
                        ec.logger.warn("FTL source target not found at location: ${loc}")
                        return ""
                    }

                    String canonicalPath = rr.getUrl()?.toString() ?: loc
                    if (visited.contains(canonicalPath)) {
                        ec.logger.warn("Circular FTL inclusion detected and skipped: ${canonicalPath}")
                        return "<!-- Circular include omitted: ${loc} -->"
                    }
                    visited.add(canonicalPath)

                    String content = rr.getText()
                    if (!content) return ""

                    Pattern includePattern = Pattern.compile("<#include\\s+[\"']([^\"']+)[\"'][^>]*\\/?>", Pattern.CASE_INSENSITIVE)
                    Matcher matcher = includePattern.matcher(content)
                    StringBuffer expandedContent = new StringBuffer()

                    while (matcher.find()) {
                        String includePath = matcher.group(1)
                        String resolvedLocation

                        if (includePath.contains("://") || includePath.startsWith("/")) {
                            resolvedLocation = includePath
                        } else {
                            ResourceReference parentRef = rr.getParent()
                            resolvedLocation = parentRef != null ? "${parentRef.location}/${includePath}" : includePath
                        }

                        String embeddedXml = resolveFtlIncludes(resolvedLocation, visited)
                        matcher.appendReplacement(expandedContent, Matcher.quoteReplacement(embeddedXml))
                    }
                    matcher.appendTail(expandedContent)
                    return expandedContent.toString()
                }

                def escapeXml = { String str ->
                    if (!str) return ""
                    return str.replace("&", "&amp;")
                              .replace("<", "&lt;")
                              .replace(">", "&gt;")
                              .replace("\"", "&quot;")
                              .replace("'", "&apos;")
                }

                def ignoredAttributes = [
                    'nodeName', '_moquiTag', 'tagName', 'type', '@type', 'mariaId', 'id', 'attributes', 
                    'ai-intent', 'children', 'widgets', 'subscreens', 'screen', 'location', 'pathIndex'
                ]

                def resolveNodeTagName = { Map nodeMap ->
                    if (!nodeMap) return "container"
                    String raw = nodeMap.nodeName ?: nodeMap._moquiTag ?: nodeMap.tag ?: nodeMap.tagName ?: nodeMap.type ?: nodeMap['@type']
                    if (!raw && nodeMap.name && (nodeMap.children || nodeMap.attributes || nodeMap.name.contains("-"))) {
                        raw = nodeMap.name
                    }
                    return (raw ?: "container").toString().replaceAll("^@", "")
                }

                def buildXmlNode
                buildXmlNode = { Map nodeMap, int indentLevel ->
                    if (!nodeMap) return ""

                    String rawTag = resolveNodeTagName(nodeMap)

                    if (rawTag == "screen" || rawTag == "widgets") {
                        StringBuilder rootSb = new StringBuilder()
                        List rootChildren = []
                        if (nodeMap.children instanceof List) rootChildren.addAll(nodeMap.children)
                        if (nodeMap.widgets instanceof List) rootChildren.addAll(nodeMap.widgets)

                        rootChildren.each { Object child ->
                            if (child instanceof Map) rootSb.append(buildXmlNode((Map) child, indentLevel))
                        }
                        return rootSb.toString()
                    }

                    String tagName = rawTag
                    String indent = "    " * indentLevel
                    StringBuilder sb = new StringBuilder("${indent}<${tagName}")
                    List childrenList = []

                    Map attrs = [:]
                    if (nodeMap.attributes instanceof Map) {
                        attrs.putAll(nodeMap.attributes as Map)
                    }

                    nodeMap.each { Object kObj, Object v ->
                        if (v == null) return
                        String k = kObj.toString()

                        if (k == 'children' || k == 'widgets') {
                            if (v instanceof List) childrenList.addAll((List) v)
                            else if (v instanceof Map) childrenList.add((Map) v)
                        } else if (!ignoredAttributes.contains(k)) {
                            if (k == 'name' && (v.toString() == rawTag || attrs.containsKey('name'))) {
                                return
                            }
                            if (!(v instanceof Map) && !(v instanceof List) && !attrs.containsKey(k)) {
                                String valStr = v.toString().trim()
                                if (valStr.length() > 0) {
                                    attrs[k] = valStr
                                }
                            }
                        }
                    }

                    attrs.each { String ak, Object av ->
                        if (av != null) {
                            sb.append(" ${ak}=\"${escapeXml(av.toString())}\"")
                        }
                    }

                    if (childrenList) {
                        sb.append(">\n")
                        childrenList.each { Object child ->
                            if (child instanceof Map) {
                                sb.append(buildXmlNode((Map) child, indentLevel + 1))
                            }
                        }
                        sb.append("${indent}</${tagName}>\n")
                    } else {
                        sb.append("/>\n")
                    }
                    return sb.toString()
                }

                def buildSubscreensXml = { Map subsMap ->
                    if (!subsMap) return ""
                    Map sAttrs = (subsMap.attributes instanceof Map) ? (subsMap.attributes as Map) : [:]
                    String defItem = subsMap.defaultItem ?: sAttrs.get('default-item') ?: sAttrs.get('defaultItem') ?: ""
                    String defaultAttr = defItem ? " default-item=\"${escapeXml(defItem.toString())}\"" : ""
                    StringBuilder ssb = new StringBuilder("    <subscreens${defaultAttr}>\n")

                    List subItems = []
                    if (subsMap.children instanceof List) subItems.addAll(subsMap.children)
                    else if (subsMap.widgets instanceof List) subItems.addAll(subsMap.widgets)

                    subItems.each { Object item ->
                        if (item instanceof Map) {
                            Map itemAttrs = (item.attributes instanceof Map) ? (item.attributes as Map) : [:]
                            String sName = (item.name && item.name != "subscreens-item") ? item.name : (itemAttrs.get('name') ?: "")
                            String sLoc = item.location ?: itemAttrs.get('location') ?: ""
                            String sTitle = item.menuTitle ?: itemAttrs.get('menu-title') ?: itemAttrs.get('menuTitle') ?: ""

                            ssb.append("        <subscreens-item")
                            if (sName) ssb.append(" name=\"${escapeXml(sName)}\"")
                            if (sLoc) ssb.append(" location=\"${escapeXml(sLoc)}\"")
                            if (sTitle && sTitle != sName) ssb.append(" menu-title=\"${escapeXml(sTitle)}\"")
                            ssb.append("/>\n")
                        }
                    }
                    ssb.append("    </subscreens>\n")
                    return ssb.toString()
                }

                if (location) {
                    xmlText = resolveFtlIncludes(location, new HashSet<String>())
                } else if (layoutTree instanceof CharSequence) {
                    // Non-XML, Markdown, or already stringified buffer
                    xmlText = layoutTree.toString()
                } else if (layoutTree instanceof Map) {
                    List topParameters   = []
                    List topTransitions  = []
                    Map  topSubscreens   = (layoutTree.subscreens instanceof Map) ? (layoutTree.subscreens as Map) : null
                    List topActions      = []
                    List widgetNodes     = []

                    def collectNodes
                    collectNodes = { Object nodeObj ->
                        if (!(nodeObj instanceof Map)) return
                        Map node = (Map) nodeObj
                        String tag = resolveNodeTagName(node)

                        if (tag == "parameter") {
                            topParameters.add(node)
                        } else if (tag == "transition") {
                            topTransitions.add(node)
                        } else if (tag == "subscreens") {
                            if (!topSubscreens) topSubscreens = node
                        } else if (tag == "actions") {
                            topActions.add(node)
                        } else if (tag == "screen") {
                            List ch = []
                            if (node.children instanceof List) ch.addAll(node.children)
                            if (node.widgets instanceof List) ch.addAll(node.widgets)
                            ch.each { collectNodes(it) }
                        } else if (tag == "widgets") {
                            List ch = []
                            if (node.children instanceof List) ch.addAll(node.children)
                            if (node.widgets instanceof List) ch.addAll(node.widgets)
                            ch.each { widgetNodes.add((Map) it) }
                        } else {
                            widgetNodes.add(node)
                        }
                    }

                    collectNodes(layoutTree)

                    StringBuilder paramsSb = new StringBuilder()
                    topParameters.each { Map pNode ->
                        paramsSb.append(buildXmlNode(pNode, 1))
                    }

                    StringBuilder transitionsSb = new StringBuilder()
                    topTransitions.each { Map tNode ->
                        transitionsSb.append(buildXmlNode(tNode, 1))
                    }

                    String subscreensText = ""
                    if (topSubscreens) {
                        subscreensText = buildSubscreensXml(topSubscreens)
                    }

                    StringBuilder actionsSb = new StringBuilder()
                    topActions.each { Map aNode ->
                        actionsSb.append(buildXmlNode(aNode, 1))
                    }

                    StringBuilder widgetsSb = new StringBuilder()
                    widgetNodes.each { Map wNode ->
                        widgetsSb.append(buildXmlNode(wNode, 2))
                    }

                    Map rootAttrs = [:]
                    if (layoutTree.attributes instanceof Map) rootAttrs.putAll(layoutTree.attributes as Map)
                    layoutTree.each { k, v ->
                        if (v != null && !ignoredAttributes.contains(k.toString()) && !(v instanceof Map) && !(v instanceof List)) {
                            rootAttrs[k.toString()] = v.toString()
                        }
                    }
                    if (topSubscreens && !rootAttrs.containsKey("default-subscreen")) {
                        Map sAttrs = (topSubscreens.attributes instanceof Map) ? (topSubscreens.attributes as Map) : [:]
                        String dItem = topSubscreens.defaultItem ?: sAttrs.get('default-item') ?: sAttrs.get('defaultItem')
                        if (dItem) rootAttrs["default-subscreen"] = dItem
                    }

                    StringBuilder rootAttrSb = new StringBuilder()
                    rootAttrs.each { ak, av ->
                        if (ak != "xmlns:xsi" && ak != "xsi:noNamespaceSchemaLocation") {
                            rootAttrSb.append(" ${ak}=\"${escapeXml(av.toString())}\"")
                        }
                    }

                    xmlText = """<?xml version="1.0" encoding="UTF-8"?>
<screen xmlns:xsi="http://www.w3.org/2001/XMLSchema-instance" xsi:noNamespaceSchemaLocation="http://moqui.org/xsd/xml-screen-3.xsd"${rootAttrSb.toString()}>
${paramsSb.toString()}${transitionsSb.toString()}${subscreensText}${actionsSb.toString()}    <widgets>
${widgetsSb.toString()}    </widgets>
</screen>"""
                } else {
                    xmlText = ""
                }

import org.moqui.resource.ResourceReference

String effectiveUri = artifactUri ? artifactUri.trim().replace('\\', '/') : ""
if (effectiveUri.contains("runtime/component/")) {
    effectiveUri = "component://" + effectiveUri.substring(effectiveUri.indexOf("runtime/component/") + "runtime/component/".length())
}

String content = ""
ResourceReference rr = ec.resource.getLocationReference(effectiveUri)
if (rr != null && rr.exists) {
    content = rr.getText() ?: ""
    context.status = "SUCCESS"
} else {
    context.status = "NOT_FOUND"
}

context.rawXml = content
context.rawText = content

                import groovy.json.JsonSlurper
                import groovy.xml.XmlUtil
                import groovy.xml.XmlParser
                import java.io.File
                import java.util.regex.Matcher
                import java.util.regex.Pattern
                import org.moqui.resource.ResourceReference

                context.errorList = []
                context.stubbedScreens = []

                String effectiveUri = artifactUri ? artifactUri.trim().replace('\\', '/') : ""
                if (effectiveUri.contains("runtime/component/")) {
                    effectiveUri = "component://" + effectiveUri.substring(effectiveUri.indexOf("runtime/component/") + "runtime/component/".length())
                }

                if (!effectiveUri || !effectiveUri.startsWith("component://")) {
                    ec.logger.error("❌ Cannot write XML file: Invalid artifactUri: ${artifactUri}")
                    context.status = "INVALID_URI"
                    return
                }

                String rawXml = xmlText ? xmlText.trim() : ""

                if (!rawXml && metaJsonBuffer) {
                    Map layoutTree = null
                    if (metaJsonBuffer instanceof Map) {
                        layoutTree = (Map) metaJsonBuffer
                    } else if (metaJsonBuffer instanceof CharSequence && metaJsonBuffer.toString().trim().startsWith('{')) {
                        layoutTree = new JsonSlurper().parseText(metaJsonBuffer.toString()) as Map
                    }

                    if (layoutTree) {
                        Map compileResult = ec.service.sync().name("org.moqui.ide.AgiIdeServices.compile#TreeToXml")
                            .parameter("layoutTree", layoutTree)
                            .call()
                        rawXml = compileResult.xmlText
                    }
                }

                if (!rawXml || rawXml.trim().length() == 0) {
                    ec.logger.error("❌ XML content is empty. Save aborted to prevent file corruption.")
                    context.status = "COMPILATION_ERROR"
                    return
                }

                String cleanedXml = rawXml

                if (autoCorrect) {
                    cleanedXml = cleanedXml.replaceAll(/(?s)(<transition\b[^>]*>.*?<actions\b[^>]*>)(.*?)(<(?:default|conditional)-response\b[^>]*\/>)(.*?)(<\/actions>)(.*?)(<\/transition>)/) {
                        all, tOpen, actPre, respTag, actPost, actClose, tPost, tClose ->
                        "${tOpen}${actPre}${actPost}${actClose}\n    ${respTag}${tPost}${tClose}"
                    }

                    if (cleanedXml.contains("<container-row") || cleanedXml.contains("<container-col")) {
                        cleanedXml = cleanedXml.replaceAll(/<container-row\b[^>]*>/, '<container style="row q-col-gutter-md">')
                        cleanedXml = cleanedXml.replaceAll(/<\/container-row>/, '</container>')
                        cleanedXml = cleanedXml.replaceAll(/<container-col\b[^>]*md="(\d+)"[^>]*>/, '<container style="col-12 col-md-$1">')
                        cleanedXml = cleanedXml.replaceAll(/<container-col\b[^>]*>/, '<container style="col-12 col-md">')
                        cleanedXml = cleanedXml.replaceAll(/<\/container-col>/, '</container>')
                    }

                    if (cleanedXml.contains("<subscreens-tabs")) {
                        cleanedXml = cleanedXml.replaceAll(/<subscreens-tabs\b([^>]*)\/>/, '<subscreens-menu$1 type="tab"/>')
                    }

                    if (cleanedXml.contains('<container name="display"/>') || cleanedXml.contains('<container name="display">')) {
                        cleanedXml = cleanedXml.replaceAll(/<container name="display"\s*\/?>/, '<display/>')
                        cleanedXml = cleanedXml.replaceAll(/<\/container>/, '')
                    }

                    if (cleanedXml.contains("<subscreens>") || (cleanedXml.contains("<subscreens ") && !cleanedXml.contains("default-item="))) {
                        Matcher itemMatcher = (cleanedXml =~ /<subscreens-item\s+[^>]*name="([^"]+)"/)
                        if (itemMatcher.find()) {
                            String firstItem = itemMatcher.group(1)
                            cleanedXml = cleanedXml.replaceFirst(/<subscreens(\s*)/, '<subscreens default-item="' + firstItem + '"$1')
                        }
                    }
                }

                try {
                    javax.xml.parsers.DocumentBuilderFactory dbf = javax.xml.parsers.DocumentBuilderFactory.newInstance()
                    dbf.setNamespaceAware(true)
                    javax.xml.parsers.DocumentBuilder db = dbf.newDocumentBuilder()
                    db.parse(new org.xml.sax.InputSource(new java.io.StringReader(cleanedXml)))
                } catch (Exception parseEx) {
                    ec.logger.error("❌ XML Syntax/Schema Parse Error in ${effectiveUri}: ${parseEx.message}")
                    context.errorList.add("XML Syntax/Schema Parse Error: " + parseEx.message)
                    context.status = "XML_PARSE_ERROR"
                    return
                }

                if (verifyEntities) {
                    Set<String> verifiedEntities = new HashSet<>()
                    Matcher entityMatcher = (cleanedXml =~ /(?:entity-name|entity)="([a-zA-Z0-9_\.]+)"/)
                    while (entityMatcher.find()) {
                        String entName = entityMatcher.group(1)
                        if (!verifiedEntities.contains(entName)) {
                            verifiedEntities.add(entName)
                            try {
                                if (!ec.entity.isEntityDefined(entName)) {
                                    context.errorList.add("Entity definition not found for [${entName}].")
                                }
                            } catch (Exception entEx) {
                                context.errorList.add("Entity [${entName}] lookup error: ${entEx.message}")
                            }
                        }
                    }

                    if (context.errorList) {
                        ec.logger.error("❌ Entity verification failed for ${effectiveUri}: ${context.errorList}")
                        context.status = "ENTITY_NOT_FOUND"

                        context.errorList.each { String errMsg ->
                            ec.message.addError(errMsg)
                        }
                        return
                    }
                }

                if (autoStubSubscreens) {
                    Matcher subItemMatcher = (cleanedXml =~ /<subscreens-item\s+[^>]*location="([^"]+)"(?:\s+[^>]*menu-title="([^"]+)")?/)
                    while (subItemMatcher.find()) {
                        String subLoc = subItemMatcher.group(1)
                        String subTitle = subItemMatcher.group(2) ?: ""

                        if (!subTitle) {
                            Matcher nameMatcher = (subItemMatcher.group(0) =~ /name="([^"]+)"/)
                            if (nameMatcher.find()) subTitle = nameMatcher.group(1)
                        }

                        if (subLoc && subLoc.startsWith("component://")) {
                            ResourceReference subRr = ec.resource.getLocationReference(subLoc)
                            if (subRr == null || !subRr.exists) {
                                String subRelPath = subLoc.replace("component://", "")
                                File subPhysical = new File("runtime/component/" + subRelPath)
                                subPhysical.getParentFile().mkdirs()

                                String stubXml = """<?xml version="1.0" encoding="UTF-8"?>
<screen xmlns:xsi="http://www.w3.org/2001/XMLSchema-instance"
        xsi:noNamespaceSchemaLocation="http://moqui.org/xsd/xml-screen-3.xsd"
        require-authentication="true">
    <widgets>
        <container style="q-pa-md">
            <container style="q-card q-pa-md bg-white rounded-borders shadow-1">
                <label type="h5" text="${subTitle ?: 'Module Placeholder'}" style="text-grey-9 q-mb-sm"/>
                <label type="p" text="This subscreen is in DRAFT status. Use AGI-IDE to plan and build this screen." style="text-grey-7"/>
            </container>
        </container>
    </widgets>
</screen>"""
                                subPhysical.text = stubXml
                                context.stubbedScreens.add(subLoc)
                                ec.logger.info("🌱 [save#ScreenXml] Auto-stubbed missing subscreen: ${subLoc}")
                            }
                        }
                    }
                }

                String relPath = effectiveUri.replace("component://", "")
                File physicalFile = new File("runtime/component/" + relPath)
                if (!physicalFile.exists()) {
                    physicalFile.getParentFile().mkdirs()
                }

                ResourceReference rr = ec.resource.getLocationReference(effectiveUri)
                if (rr == null || !rr.supportsWrite()) {
                    ec.logger.error("❌ Cannot write XML file: ResourceLocation ${effectiveUri} is not writable.")
                    context.status = "NOT_WRITABLE"
                    return
                }

                String prettyXml = cleanedXml
                try {
                    def parsedXml = new groovy.xml.XmlParser(false, false).parseText(cleanedXml)
                    prettyXml = XmlUtil.serialize(parsedXml)
                } catch (Exception formatEx) {
                    ec.logger.warn("⚠️ Could not pretty-print XML, writing sanitized output directly: ${formatEx.message}")
                }

                rr.putText(prettyXml)
                ec.logger.info("💾 [save#ScreenXml] Successfully written validated XML to file: ${rr.getUrl()}")

                try {
                    ec.resource.clearAllCaches()
                    ec.screen.clearScreenCache(true)
                } catch (Exception ignored) {}

                context.status = "SUCCESS"
                context.savedFilePath = rr.getUrl()

import groovy.json.JsonSlurper
import groovy.json.JsonOutput
import java.security.MessageDigest
import org.moqui.resource.ResourceReference

String effectiveXml = xmlContent ?: xmlText ?: ""

// Non-XML guard: skip SAX/DOM parsing for markdown, json, or text files
if (artifactUri && !artifactUri.endsWith('.xml')) {
    context.layoutTree = null
    context.astTree = null
    return
}

def generateFallbackId = { String uri, String xpath ->
    String raw = "${uri}#${xpath}"
    MessageDigest md = MessageDigest.getInstance("MD5")
    byte[] digest = md.digest(raw.getBytes("UTF-8"))
    String hex = digest.encodeHex().toString().substring(0, 12)
    return "maria_${hex}"
}

def enrichAstNodes
enrichAstNodes = { Map node, String currentPath, int childIdx ->
    if (!node) return

    String tagName = node._moquiTag ?: (node.tagName ?: node.type ?: node['@type'] ?: "node").toString().replaceAll("^@", "")
    String explicitId = node.id ?: node.name ?: node.attributes?.name ?: node.attributes?.id

    String elementPath = "${currentPath}/${tagName}[${childIdx}]"
    if (explicitId) elementPath += "@${explicitId}"

    if (!node.mariaId) {
        if (explicitId) {
            node.mariaId = "maria_${explicitId.replaceAll('[^a-zA-Z0-9_]', '_')}"
        } else {
            node.mariaId = generateFallbackId(artifactUri, elementPath)
        }
    }

    List childrenList = []
    if (node.children instanceof List) childrenList.addAll(node.children)
    if (node.widgets instanceof List) childrenList.addAll(node.widgets)

    int idx = 0
    childrenList.each { Object child ->
        if (child instanceof Map) {
            enrichAstNodes((Map) child, elementPath, idx++)
        }
    }
}

def parseXmlNodeDirect
parseXmlNodeDirect = { groovy.util.Node xmlNode ->
    Map m = [
        _moquiTag : xmlNode.name()?.toString(),
        name      : xmlNode.name()?.toString(),
        attributes: xmlNode.attributes() ?: [:],
        children  : []
    ]
    xmlNode.children().each { child ->
        if (child instanceof groovy.util.Node) {
            m.children.add(parseXmlNodeDirect(child))
        }
    }
    return m
}

def extractSubscreensBlock = { Map parsedNode ->
    Map sAttrs = (parsedNode.attributes instanceof Map) ? (parsedNode.attributes as Map) : [:]
    String defItem = sAttrs.get('default-item') ?: sAttrs.get('defaultItem') ?: ""

    List cleanSubItems = []
    (parsedNode.children ?: []).each { subChild ->
        if (subChild instanceof Map) {
            Map cAttrs = (subChild.attributes instanceof Map) ? (subChild.attributes as Map) : [:]
            String realName = cAttrs.get('name') ?: (subChild.name != 'subscreens-item' ? subChild.name : "") ?: ""
            String menuTitle = cAttrs.get('menu-title') ?: cAttrs.get('menuTitle') ?: realName

            cleanSubItems.add([
                _moquiTag : "subscreens-item",
                '@type'   : "m-subscreens-item",
                name      : realName,
                menuTitle : menuTitle,
                location  : cAttrs.get('location') ?: "",
                attributes: cAttrs
            ])
        }
    }

    return [
        _moquiTag  : "subscreens",
        defaultItem: defItem,
        children   : cleanSubItems
    ]
}

try {
    Map finalTree = null

    if (effectiveXml && effectiveXml.trim()) {
        groovy.xml.XmlParser parser = new groovy.xml.XmlParser(false, false)
        parser.setFeature("http://apache.org/xml/features/nonvalidating/load-external-dtd", false)
        groovy.util.Node rootXml = parser.parseText(effectiveXml)

        List rootChildren = []
        Map rootSubscreens = null

        rootXml.children().each { ch ->
            if (ch instanceof groovy.util.Node) {
                Map parsed = parseXmlNodeDirect(ch)
                if (parsed._moquiTag == "subscreens") {
                    rootSubscreens = extractSubscreensBlock(parsed)
                } else {
                    rootChildren.add(parsed)
                }
            }
        }

        finalTree = [
            _moquiTag : "screen",
            screen    : artifactUri ? artifactUri.replaceAll('^component://[^/]+/screen/', '').replaceAll('\\.xml$', '') : "GeneratedScreen",
            location  : artifactUri,
            subscreens: rootSubscreens,
            children  : rootChildren
        ]
    }

    if (finalTree == null && artifactUri) {
        ResourceReference rr = ec.resource.getLocationReference(artifactUri)
        if (rr != null && rr.exists) {
            groovy.xml.XmlParser parser = new groovy.xml.XmlParser(false, false)
            parser.setFeature("http://apache.org/xml/features/nonvalidating/load-external-dtd", false)
            groovy.util.Node rootXml = parser.parseText(rr.getText())

            List rootChildren = []
            Map rootSubscreens = null

            rootXml.children().each { ch ->
                if (ch instanceof groovy.util.Node) {
                    Map parsed = parseXmlNodeDirect(ch)
                    if (parsed._moquiTag == "subscreens") {
                        rootSubscreens = extractSubscreensBlock(parsed)
                    } else {
                        rootChildren.add(parsed)
                    }
                }
            }

            finalTree = [
                _moquiTag : "screen",
                screen    : artifactUri.replaceAll('^component://[^/]+/screen/', '').replaceAll('\\.xml$', ''),
                location  : artifactUri,
                subscreens: rootSubscreens,
                children  : rootChildren
            ]
        }
    }

    if (finalTree != null) {
        enrichAstNodes(finalTree, "", 0)
        context.layoutTree = finalTree
        context.astTree = finalTree
        ec.logger.info("✅ [parse#XmlToTree] Successfully parsed and stamped AST for: ${artifactUri}")
    } else {
        ec.logger.warn("⚠️ [parse#XmlToTree] Could not produce AST for: ${artifactUri}")
    }

} catch (Exception e) {
    ec.logger.error("❌ [parse#XmlToTree] Error parsing AST for ${artifactUri}: ${e.message}", e)
    throw e
}

import java.nio.file.Path
import java.nio.file.Paths
import groovy.io.FileType

String compName = (targetComponent ?: 'nursinghome').trim()
String term = searchTerm ? searchTerm.trim().toLowerCase() : null
Map<String, Map> artifactMap = [:]

def dbArtifacts = ec.entity.find("org.moqui.ai.AgiArtifact").list()
dbArtifacts.each { art ->
    String path = art.artifactPath ?: ""
    if (path.startsWith("component://${compName}/")) {
        String relPath = path.replace("component://${compName}/", "")
        String fName = relPath.substring(relPath.lastIndexOf('/') + 1)

        if (!term || relPath.toLowerCase().contains(term) || path.toLowerCase().contains(term) || fName.toLowerCase().contains(term)) {
            artifactMap[path] = [
                screenName   : fName,
                label        : relPath,
                artifactPath : path,
                value        : path,
                componentName: compName,
                agiArtifactId: art.agiArtifactId,
                status       : art.artifactStatusEnumId ?: "AasDraft",
                type         : fName.endsWith(".qvt.js") ? 'QVT' : 'XML'
            ]
        }
    }
}

File compDir = new File("runtime/component/${compName}")
if (compDir.exists() && compDir.isDirectory()) {
    Path compBasePath = compDir.toPath()

    compDir.eachFileRecurse(FileType.FILES) { File f ->
        String filename = f.name
        if (filename.startsWith('.')) return

        Path relPath = compBasePath.relativize(f.toPath())
        String relPathStr = relPath.toString().replace('\\', '/')
        String fullUri = "component://${compName}/${relPathStr}"

        if (artifactMap.containsKey(fullUri)) return

        String artifactType = null
        if (filename.endsWith('.xml') && relPathStr.startsWith('screen/')) {
            artifactType = 'XML'
        } else if (filename.endsWith('.qvt.js')) {
            artifactType = 'QVT'
        } else if (relPathStr.startsWith('service/') && (filename.endsWith('Services.xml') || filename.endsWith('.groovy'))) {
            artifactType = 'SRV'
        } else if (relPathStr.startsWith('entity/') && filename.endsWith('Entities.xml')) {
            artifactType = 'ENT'
        } else if (relPathStr.startsWith('test/') && filename.endsWith('Test.xml')) {
            artifactType = 'TST'
        } else if (filename.endsWith('.ftl') || filename.endsWith('.xsl-fo')) {
            artifactType = 'RPT'
        }

        if (artifactType) {
            if (!term || relPathStr.toLowerCase().contains(term) || fullUri.toLowerCase().contains(term) || filename.toLowerCase().contains(term)) {
                artifactMap[fullUri] = [
                    screenName   : filename,
                    label        : relPathStr,
                    artifactPath : fullUri,
                    value        : fullUri,
                    componentName: compName,
                    agiArtifactId: null,
                    status       : "AasActive",
                    type         : artifactType
                ]
            }
        }
    }
}

context.artifacts = new ArrayList(artifactMap.values())
ec.logger.info("📦 [get#KnownArtifacts] Returned ${context.artifacts.size()} artifacts for ${compName}")

import groovy.json.JsonOutput

org.moqui.resource.ResourceReference rr = ec.resource.getLocationReference(artifactUri)
if (rr != null) {
    String formattedJson = JsonOutput.prettyPrint(JsonOutput.toJson(themeData))
    rr.putText(formattedJson)
    context.status = "SUCCESS"
} else {
    context.status = "FILE_NOT_FOUND"
}

import groovy.json.JsonSlurper

org.moqui.resource.ResourceReference rr = ec.resource.getLocationReference(artifactUri)
if (rr != null && rr.exists) {
    context.themeData = new JsonSlurper().parseText(rr.getText())
    context.status = "SUCCESS"
} else {
    context.status = "FILE_NOT_FOUND"
}

String activeUserId = userId ?: ec.user.getUserId() ?: "system_ide_user" int count = 0
String rawUri = artifactUri ? artifactUri.trim().replace('\\', '/') : "" String effectiveUri = rawUri if (effectiveUri.contains("runtime/component/")) { effectiveUri = "component://" + effectiveUri.substring(effectiveUri.indexOf("runtime/component/") + "runtime/component/".length()) }
ec.logger.warn("🧹 [FORENSIC clear#WorkspaceBuffer] REQUEST: rawUri=[${rawUri}], effectiveUri=[${effectiveUri}], clearAll=[${clearAll}], user=[${activeUserId}]")
if (clearAll) { count = ec.entity.find("org.moqui.ai.WorkspaceBuffer") .condition("userId", activeUserId) .deleteAll() ec.logger.warn("🧹 [FORENSIC clear#WorkspaceBuffer] Cleared all (${count}) buffers for user: ${activeUserId}") } else if (effectiveUri) { def cond = ec.entity.conditionFactory.makeCondition([ ec.entity.conditionFactory.makeCondition("artifactUri", "equals", effectiveUri), ec.entity.conditionFactory.makeCondition("artifactUri", "equals", artifactUri) ], org.moqui.entity.EntityCondition.JoinOperator.OR)
count = ec.entity.find("org.moqui.ai.WorkspaceBuffer") .condition(cond) .deleteAll() ec.logger.warn("🧹 [FORENSIC clear#WorkspaceBuffer] Deleted ${count} buffer record(s) matching: ${effectiveUri} / ${artifactUri}") }
context.status = "SUCCESS" context.deletedCount = count

import org.moqui.resource.ResourceReference

ec.logger.warn("🗑️ [delete#WorkspaceArtifact] Full artifact purge for: ${artifactLocation}")

ResourceReference rr = ec.resource.getLocationReference(artifactLocation)
boolean fileExisted = false
boolean fileDeleted = false
if (rr != null && rr.exists) {
    fileExisted = true
    fileDeleted = rr.delete()
}

try {
    ec.entity.find("org.moqui.ai.WorkspaceBuffer")
            .condition("artifactUri", artifactLocation)
            .deleteAll()
} catch (Exception e) {
    ec.logger.warn("⚠️ [delete#WorkspaceArtifact] Buffer cleanup failed: ${e.message}")
}

try {
    ec.resource.clearAllCaches()
} catch (Exception ignored) {}

context.status = fileDeleted ? "SUCCESS" : (fileExisted ? "DELETE_FAILED" : "FILE_NOT_FOUND")
ec.message.addMessage("Artifact deleted successfully: ${artifactLocation}")

import org.moqui.resource.ResourceReference import groovy.xml.XmlParser import java.util.regex.Pattern
String comp = (targetComponent ?: 'nursinghome').trim() String rootUri = rootScreenUri ?: "component://${comp}/screen/${comp}.xml"
Map stats = [total: 0, built: 0, placeholder: 0, empty: 0, tested: 0] Set<String> visited = new HashSet<>()
def analyzeScreenNode analyzeScreenNode = { String artifactUri, String parentName, String explicitTitle -> if (!artifactUri || visited.contains(artifactUri)) return null visited.add(artifactUri) stats.total++
String cleanName = artifactUri.replaceAll("^.*/", "").replaceAll("\\.xml\$", "") Map node = [ artifactUri : artifactUri, screenName : cleanName, displayTitle: explicitTitle ?: cleanName, parentName : parentName, status : "empty", widgetCount : 0, formCount : 0, transCount : 0, subscreenCount: 0, children : [] ]
ResourceReference rr = ec.resource.getLocationReference(artifactUri) if (rr == null || !rr.exists) { node.status = "empty" stats.empty++ return node }
String content = "" try { content = rr.getText() ?: "" } catch (Exception e) { ec.logger.warn("⚠️ [get#ComponentScreenHierarchy] Error reading ${artifactUri}: ${e.message}") }
if (!content || content.trim().isEmpty()) { node.status = "empty" stats.empty++ return node }
def artRecord = ec.entity.find("org.moqui.ai.AgiArtifact") .condition("artifactPath", artifactUri) .one() boolean hasTestRecord = (artRecord?.artifactStatusEnumId == "AasActive" && artRecord?.completedIntentCount > 0)
int transCount = 0 def transMatcher = content =~ /<transition\b/ while (transMatcher.find()) transCount++ node.transCount = transCount
int formCount = 0 def formMatcher = content =~ /<form-(?:single|list)\b/ while (formMatcher.find()) formCount++ node.formCount = formCount
boolean isStubCard = content.contains("Module Placeholder") || content.contains("This subscreen is in DRAFT status") || (content.contains("<label") && !content.contains("<form-") && !content.contains("<subscreens-menu") && transCount == 0)
if (isStubCard) { node.status = "placeholder" stats.placeholder++ } else if (hasTestRecord) { node.status = "tested" stats.tested++ } else if (formCount > 0 || transCount > 0 || content.contains("<subscreens-menu") || content.contains("<container style=")) { node.status = "built" stats.built++ } else { node.status = "empty" stats.empty++ }
List<Map> declaredSubscreens = [] try { def subsMatcher = content =~ /<subscreens-item\s+[^>]*name="([^"]+)"\s+[^>]*location="([^"]+)"(?:\s+[^>]*menu-title="([^"]+)")?/ while (subsMatcher.find()) { declaredSubscreens.add([ name: subsMatcher.group(1), location: subsMatcher.group(2), menuTitle: subsMatcher.group(3) ?: subsMatcher.group(1) ]) } } catch (Exception ex) { ec.logger.warn("⚠️ [get#ComponentScreenHierarchy] Error parsing subscreens for ${artifactUri}: ${ex.message}") }
node.subscreenCount = declaredSubscreens.size() declaredSubscreens.each { sub -> Map childNode = analyzeScreenNode(sub.location, cleanName, sub.menuTitle) if (childNode) node.children.add(childNode) }
return node }
Map rootHierarchy = analyzeScreenNode(rootUri, null, comp.capitalize() + " Root") context.rootNode = rootHierarchy context.summaryStats = stats ec.logger.info("📊 [get#ComponentScreenHierarchy] Evaluated ${stats.total} screens for '${comp}': Built=${stats.built}, Stubs=${stats.placeholder}, Empty=${stats.empty}, Tested=${stats.tested}")

errorList = []
isValid = true
String targetUri = artifactUri

if (!targetUri.endsWith(".xml")) {
    context.isValid = true
    context.errorList = []
    return
}

String textToValidate = xmlContent
if (!textToValidate || !textToValidate.trim()) {
    org.moqui.resource.ResourceReference rr = ec.resource.getLocationReference(targetUri)
    if (!rr || !rr.exists) {
        errorList.add("File does not exist: ${targetUri}")
        context.isValid = false
        context.errorList = errorList
        return
    }
    textToValidate = rr.getText()
}

org.moqui.util.MNode screenNode = null
try {
    screenNode = org.moqui.util.MNode.parseText(targetUri, textToValidate)
} catch (Exception pe) {
    errorList.add("XML Syntax Parse Error: " + pe.message)
    context.isValid = false
    context.errorList = errorList
    return
}

if (screenNode.getName() != "screen") {
    errorList.add("Root element must be <screen>, found: <${screenNode.getName()}>")
    context.isValid = false
    context.errorList = errorList
    return
}

if (screenNode.attribute("default-subscreen")) {
    errorList.add("Invalid attribute 'default-subscreen' on <screen>. Use <subscreens default-item=\"...\"> instead.")
}

org.moqui.util.MNode subscreensNode = screenNode.first("subscreens")
if (subscreensNode) {
    if (subscreensNode.first("subscreen")) {
        errorList.add("Invalid tag '<subscreen>' found inside <subscreens>. Moqui schema requires '<subscreens-item>'.")
    }

    List<org.moqui.util.MNode> items = subscreensNode.children("subscreens-item")
    for (org.moqui.util.MNode item : items) {
        String loc = item.attribute("location")
        if (loc && (loc == targetUri || loc.endsWith("/" + targetUri.substring(targetUri.lastIndexOf('/') + 1)))) {
            errorList.add("Circular Dependency: Screen declares itself as its own subscreen ('${loc}').")
        }
    }
}

try {
    org.moqui.impl.screen.ScreenDefinition screenDef = ec.screen.getScreenDefinition(targetUri)
    if (screenDef == null && !xmlContent) {
        errorList.add("Moqui ScreenFacade returned [null] ScreenDefinition for '${targetUri}'.")
    }
} catch (Exception se) {
    errorList.add("Screen Definition Instantiation Failed: " + se.message)
}

context.isValid = errorList.isEmpty()
context.errorList = errorList
